const g = $input.first().json;
const e = g.estado_actual || {};
const ctx = JSON.stringify({estado_actual: e, prediccion_30min: g.prediccion_30min, alertas_activas: g.alertas_activas, resumen_llm: g.resumen_llm});
const prompt = `Eres un agente de control de un hogar inteligente.
Tienes disponibles estas herramientas:
- activar_actuador(dispositivo, estado)  // dispositivo: led o buzzer
- enviar_notificacion(mensaje)
- registrar_evento(descripcion)

Estado del gemelo digital (JSON): ${ctx}

Umbrales: gas critico > 400 ppm, sonido alto > 80 dB, distancia baja < 20 cm.
Decide que acciones ejecutar. Responde SOLO en JSON con esta estructura:
{\"acciones\":[{\"herramienta\":\"activar_actuador\",\"parametros\":{\"dispositivo\":\"led\",\"estado\":true}}],\"razonamiento\":\"...\"}`;
return [{ json: { model: 'qwen2.5:0.5b', prompt: prompt, stream: false, format: 'json' } }];

const resp = $json.response || $json.data || '';
let decision;
try { decision = JSON.parse(resp); } catch(err) { decision = { acciones: [], razonamiento: 'error parse: ' + String(resp).slice(0,150) }; }
const acciones = decision.acciones || [];
const ejecutadas = [];
for (const acc of acciones) {
  const tool = acc.herramienta || acc.tool;
  const p = acc.parametros || acc.params || {};
  if (tool === 'activar_actuador') {
    try {
      await this.helpers.httpRequest({ method:'POST', url:'http://nodered:1880/agente/accion', body:{dispositivo:p.dispositivo, estado:p.estado}, json:true });
      ejecutadas.push('actuador ' + p.dispositivo + '=' + p.estado);
    } catch(err) { ejecutadas.push('error actuador: ' + err.message); }
  } else if (tool === 'enviar_notificacion') {
    ejecutadas.push('notif: ' + (p.mensaje||''));
  } else if (tool === 'registrar_evento') {
    ejecutadas.push('evento: ' + (p.descripcion||''));
  }
}
const raz = String(decision.razonamiento||'').replace(/"/g,"'").slice(0,200);
const accStr = (ejecutadas.join(' | ')||'ninguna').replace(/"/g,"'").slice(0,200);
const line = 'agente razonamiento="'+raz+'",acciones="'+accStr+'",num='+acciones.length;
try {
  await this.helpers.httpRequest({ method:'POST', url:'http://influxdb:8086/api/v2/write?org=smarthome&bucket=sensores&precision=s', headers:{'Authorization':'Token smarthome_token_2024','Content-Type':'text/plain'}, body: line });
} catch(err) {}
return [{ json: { razonamiento: decision.razonamiento, acciones_ejecutadas: ejecutadas, total: acciones.length } }];
